/**
 * Shared types for pi-cues.
 */

export type ToolName = "bash" | "read" | "edit" | "write";

export type ActionKind = "skill" | "file" | "walkup" | "inline" | "exec";

/**
 * Raw shape of pi-cues.toml as authored by the user. This is the source of
 * truth for config.schema.json (generated by `mise run schema:generate`);
 * config.ts parses and normalizes it into {@link Trigger}.
 */
export interface RawConfig {
  /** Config schema version. Must be 1. */
  version: 1;
  /** Set to false to disable the builtin walkup trigger (AGENTS.md up to the session cwd). */
  defaults?: boolean;
  /** Local telemetry settings. Only the global config's entry takes effect; project entries are ignored. */
  telemetry?: RawTelemetry;
  /** Trigger entries. Global config provides the baseline; project config entries are appended. */
  triggers?: RawTrigger[];
}

export interface RawTelemetry {
  /** Set to false to stop recording fired cues to ~/.cache/pi-cues/events.jsonl. Default true. */
  enabled?: boolean;
}

export interface RawTrigger {
  /** Tool events this trigger listens to. `bash` pairs with when.command; read/edit/write pair with when.path. */
  tools: ToolName[];
  /** Predicate. Required for skill/file; optional for walkup (omitted = every listed path event matches). */
  when?: RawWhen;
  /** skill: inject a pi skill (full text). file: inject a prompt file (truncated). walkup: collect context files up to the session cwd. inline: inject the target text itself. exec: run the target as a shell command and inject its output (bash triggers only). */
  action: ActionKind;
  /** skill: skill name(s). file: prompt file path(s), relative to the config directory (project configs must not escape it). walkup: context file name(s), e.g. AGENTS.md. inline: the literal markdown to inject. exec: the command line(s) to run, executed as-is through pi's bash tool with no placeholder interpolation. */
  target: string | string[];
  /** walkup only: picomatch patterns matched against the collected file's path relative to the session cwd (POSIX separators). "README.md" matches only the cwd-level file; use a globstar pattern to match any depth. A leading bang (exclamation) prefix is rejected. */
  exclude?: string | string[];
}

export interface RawWhen {
  /** Command basename patterns (picomatch; exact match without wildcards). Requires `bash` in tools. */
  command?: string | string[];
  /** Path globs matched against projectRelative/scopeRelative/basename bases; `!` prefix excludes. Requires read/edit/write in tools. */
  path?: string | string[];
}

export interface CueDiagnostic {
  severity: "warning" | "error";
  /** Config file path or runtime context the diagnostic belongs to. */
  source: string;
  message: string;
}

export interface TriggerWhen {
  command?: string[];
  path?: string[];
}

export interface Trigger {
  tools: ToolName[];
  /** Undefined only for walkup triggers (match every listed tool event). */
  when?: TriggerWhen;
  action: ActionKind;
  targets: string[];
  /** walkup only: picomatch patterns matched against the anchor-relative POSIX path of collected files. */
  excludes: string[];
  /** Directory containing the config file that declared this trigger; base for `file` targets. */
  configDir: string;
  /** Config file path, for diagnostics and `/cues status`. */
  source: string;
}
